{"code": "
// Call bash twice
const r1 = await tools.bash({command: "echo CODE_ONE", description: "Echo CODE_ONE"});
const r2 = await tools.bash({command: "echo CODE_TWO", description: "Echo CODE_TWO"});

// Extract the text outputs
const out1 = r1.stdout.text.trim();
const out2 = r2.stdout.text.trim();

// Console.log exactly "captured output"
console.log("captured output");

// Return the two outputs joined with a plus sign
return out1 + "+" + out2;
", "description": "Run two echo commands and join outputs"}

